DO $review$
DECLARE v jsonb; s public.est_source_review%rowtype; q public.questions%rowtype; k public.question_keys%rowtype; a jsonb; qid uuid; p jsonb; pid uuid;
BEGIN
 FOR v IN SELECT value FROM jsonb_array_elements($payload$[{"id": "clean:PSD 036", "old_status": "missing_stimulus", "status": "duplicate", "note": "Recovered the original monthly salary chart from PSD 035 page 173 and matched the full question to DAP 014 page 25. The values 2,3,2,8,6,4,2,1,11,9,3,6 sum to 57; May contributes 6. Thus 100×6/57≈10.53%, D. Reused the verified existing question.", "correct": "D", "duplicate_of": "topic:DAP 014", "question_id": "154d45d6-34c7-5c42-8567-4193574b7436", "before": {"stem": "Combined monthly salaries in 2019, in thousands of dollars: Jan 2; Feb 3; Mar 2; Apr 8; May 6; Jun 4; Jul 2; Aug 1; Sep 11; Oct 9; Nov 3; Dec 6. What is the approximate percentage of the income in May out of their total annual income?", "choices": [{"key": "A", "text": "3.41%"}, {"key": "B", "text": "5.27%"}, {"key": "C", "text": "9.52%"}, {"key": "D", "text": "10.53%"}], "correct": "D", "explanation": "The monthly values sum to 57 thousand dollars. May contributes 6 thousand, so its share is 100 × 6/57 ≈ 10.53%."}}, {"id": "clean:PSD 035", "old_status": "ocr_screened_not_verified", "status": "duplicate", "note": "Page 173 contains original Q4/Q5, already represented by DAP 013 and DAP 012. Q4: September has 30−4=26 working days; fiancée earnings=26×11×10.7=3060.2, and Adam earns (11000−3060.2)/(26×15)=20.35846 per hour, choice C. Q5: quarterly totals 7,18,14,18; first quarter is lowest, choice A. Both matched to existing verified questions, with Q5 at 6574b390-dfe4-5e0d-af07-d84c852308c3.", "correct": "C", "duplicate_of": "topic:DAP 013", "question_id": "07779610-2dd2-5d50-b2e7-7f8b4b30a7a7", "before": {"stem": "Questions 20 to 22 refer to a graph of Adam and his fiancée's combined monthly salaries (in thousands of dollars) during 2019: Jan 2, Feb 3, Mar 2, Apr 8, May 6, Jun 4, Jul 2, Aug 1, Sep 11, Oct 9, Nov 3, Dec 6. — During September, Adam worked 15 hours per day, while his fiancée worked 11 hours per day. Knowing that each one of them took 4 days off that month, and his fiancée was getting paid $10.7 per hour, how much was Adam approximately getting paid per hour?", "choices": [{"key": "A", "text": "$16.6"}, {"key": "B", "text": "$17.8"}, {"key": "C", "text": "$20.4"}, {"key": "D", "text": "$36.1"}], "correct": "C", "explanation": "Each worked 26 days. His fiancée earned 26 × 11 × 10.7 = $3,060.20. Adam's hourly rate was (11,000 − 3,060.20)/(26 × 15) ≈ $20.36, closest to $20.4."}}, {"id": "clean:HOA 077", "old_status": "missing_stimulus", "status": "duplicate", "note": "Matched original question to DAP 068 and inspected shared color graph on topic page 44. With x=3 for 2014, predicted boys=194.3×3+2020.4=2603.3; observed blue dot≈2550. Absolute error≈53.3, closest to 53, choice C.", "correct": "C", "duplicate_of": "topic:DAP 068", "question_id": "016c3282-6338-5f41-adb8-bf518964f869", "before": {"stem": "The graph shows observed values and fitted curves. Year 2011 is x = 0. Village B’s fitted line is y = 194.3x + 2,020.4. What is the closest difference between the actual number of boys in village B and the number which can be predicted from the line of best fit in 2014?", "choices": [{"key": "A", "text": "13"}, {"key": "B", "text": "26"}, {"key": "C", "text": "53"}, {"key": "D", "text": "100"}], "correct": "C", "explanation": "In 2014, x = 3. The prediction is 194.3(3) + 2,020.4 = 2,603.3 boys. The observed value is about 2,550, a difference of 53.3, closest to 53."}}, {"id": "clean:PSD 017", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "cb85dca4-370c-5de4-90b3-8f78f7b05414", "stem": "A gaming website models a customer’s total fee as f=7g+88, where g is the number of games downloaded. What does 88 represent?", "choices": [{"key": "A", "text": "The price of one downloaded game."}, {"key": "B", "text": "The fixed subscription fee."}, {"key": "C", "text": "The average games per player."}, {"key": "D", "text": "The fee for downloading 7 games."}], "type": "mcq", "correct": "B", "explanation": "The total when g=0 is 88, so it is the fixed charge independent of downloads. The coefficient 7 is the extra charge for each downloaded game.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Original PDF visually checked; isolated complete question and independently verified the solution.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 157, "extra_sources": []}, {"id": "clean:PSD 044", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "fba0c54d-cf23-5536-9898-9cea08a0bd5a", "stem": "The magnitude of average acceleration is A=Δv/Δt, where Δv>0 is the change in velocity along a fixed direction and Δt>0 is elapsed time. Which statements hold? I. Increasing Δv and decreasing Δt increases A. II. Decreasing Δv and increasing Δt increases A. III. Decreasing Δv and increasing Δt decreases A.", "choices": [{"key": "A", "text": "I only"}, {"key": "B", "text": "II only"}, {"key": "C", "text": "I and II"}, {"key": "D", "text": "I and III"}], "type": "mcq", "correct": "D", "explanation": "For positive quantities, increasing the numerator and decreasing the denominator both increase their ratio, so I is true. Decreasing the numerator and increasing the denominator both decrease it, making III true and II false.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Corrected the original physical error: its assertions used displacement Δr to infer acceleration. The repaired question consistently uses positive velocity change Δv and the valid average-acceleration formula.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 180, "extra_sources": []}, {"id": "clean:PSD 046", "old_status": "ocr_screened_not_verified", "status": "ready", "question_id": "395029ab-a088-5dcb-b2ed-37b1082a5534", "stem": "The quantity y varies directly as the cube of 2x. If y=8 when x=2, what is y when x=4?", "choices": [], "type": "grid_in", "correct": "64", "explanation": "Write y=k(2x)³. The given point gives 8=k·4³=64k, so k=1/8. At x=4, y=(1/8)·8³=64. Equivalently doubling x multiplies y by 2³=8.", "topic": "Algebra Foundations, Equations & Inequalities", "note": "Isolated complete original Q33. The opening algebra fragment lacks its first clause and remains excluded. The following laptop graph has been reunited with HOA 033/DAP 070/071.", "source_document": "Math_Question_Bank_Ghoneem_Clean.pdf", "source_page": 182, "extra_sources": []}]$payload$::jsonb) LOOP
  SELECT * INTO s FROM public.est_source_review WHERE id=v->>'id' FOR UPDATE;
  IF s.id IS NULL THEN RAISE EXCEPTION 'Missing source %',v->>'id'; END IF;
  IF EXISTS(SELECT 1 FROM public.audit_log WHERE action=coalesce(v->>'audit_action','source_review_20260928') AND target_id=s.id) THEN CONTINUE; END IF;
  IF s.review_status<>v->>'old_status' THEN RAISE EXCEPTION 'Source status changed %',s.id; END IF;
  qid=nullif(v->>'question_id','')::uuid;
  IF v->>'status'='ready' AND qid IS NOT NULL AND EXISTS(SELECT 1 FROM public.exams e JOIN public.attempts t ON t.exam_id=e.id
      WHERE qid=ANY(e.question_ids) AND t.status='in_progress' AND t.deadline_at>now()) THEN
   INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES('source_review_deferred_20260928','source_review',s.id,jsonb_build_object('reason','Active exam','proposed',v));
   CONTINUE;
  END IF;
  SELECT * INTO q FROM public.questions WHERE id=qid FOR UPDATE;
  SELECT * INTO k FROM public.question_keys WHERE question_id=qid FOR UPDATE;
  IF q.id IS NOT NULL AND v ? 'before' AND
    (q.stem IS DISTINCT FROM v->'before'->>'stem' OR q.choices IS DISTINCT FROM v->'before'->'choices' OR
     k.correct IS DISTINCT FROM v->'before'->'correct' OR k.explanation IS DISTINCT FROM v->'before'->>'explanation') THEN
    RAISE EXCEPTION 'Concurrent live question change %',qid;
  END IF;
  INSERT INTO public.audit_log(action,target_type,target_id,meta) VALUES(coalesce(v->>'audit_action','source_review_20260928'),'source_review',s.id,
    jsonb_build_object('before_source',to_jsonb(s),'before_question',to_jsonb(q),'before_key',to_jsonb(k),'decision',v-'assets'-'before'));
  IF v->>'status'='ready' THEN
   IF v->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(v->'choices') c WHERE c->>'key'=v->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid key %',s.id; END IF;
   IF v->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(v->'correct')='array' THEN v->'correct'->0 ELSE v->'correct' END,v->'correct') THEN RAISE EXCEPTION 'Grader rejects %',s.id; END IF;
   a=(coalesce(q.assets,'{}'::jsonb)-'release_hold_reason')||coalesce(v->'assets','{}'::jsonb)||jsonb_build_object(
    'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check',
    'verification_note',v->>'note','source_review_id',s.id,'verification_source',s.source_document||' page '||s.source_page);
   IF q.id IS NULL THEN
    a=a||jsonb_build_object('source','reviewed-bank-20260928','source_code',s.source_code,'source_document',s.source_document,'source_page',s.source_page);
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(qid,s.track_id,v->>'topic','medium',v->>'type',v->>'stem',v->'choices',a);
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(qid,v->'correct',v->>'explanation');
   ELSE
    UPDATE public.questions SET topic=v->>'topic',type=v->>'type',stem=v->>'stem',choices=v->'choices',assets=a WHERE id=qid;
    UPDATE public.question_keys SET correct=v->'correct',explanation=v->>'explanation' WHERE question_id=qid;
   END IF;
   FOR p IN SELECT value FROM jsonb_array_elements(coalesce(v->'parts','[]'::jsonb)) LOOP
    pid=(p->>'question_id')::uuid;
    IF EXISTS(SELECT 1 FROM public.questions WHERE id=pid) THEN RAISE EXCEPTION 'Split question already exists %',pid; END IF;
    IF p->>'type'='mcq' AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'choices') c WHERE c->>'key'=p->'correct'#>>'{}') THEN RAISE EXCEPTION 'Invalid split key %',pid; END IF;
    IF p->>'type'='grid_in' AND NOT public.answer_matches('grid_in',CASE WHEN jsonb_typeof(p->'correct')='array' THEN p->'correct'->0 ELSE p->'correct' END,p->'correct') THEN RAISE EXCEPTION 'Invalid split numeric key %',pid; END IF;
    INSERT INTO public.questions(id,track_id,topic,difficulty,type,stem,choices,assets)
     VALUES(pid,s.track_id,coalesce(p->>'topic',v->>'topic'),'medium',p->>'type',p->>'stem',p->'choices',coalesce(p->'assets','{}'::jsonb)||jsonb_build_object(
      'source','reviewed-bank-20260928','source_review_id',s.id,'source_code',s.source_code||':'||(p->>'label'),'source_document',s.source_document,'source_page',s.source_page,
      'verified_release','2026-09-28-independent-solution-and-source-check','answer_review','2026-09-28-independent-solution-and-source-check','verification_note',p->>'note'));
    INSERT INTO public.question_keys(question_id,correct,explanation) VALUES(pid,p->'correct',p->>'explanation');
   END LOOP;
  END IF;
  UPDATE public.est_source_review SET review_status=v->>'status',question_id=coalesce(qid,question_id),
   worked_answer=coalesce(v->'correct',worked_answer),duplicate_of=coalesce(v->>'duplicate_of',duplicate_of),
   review_note='Rechecked 2026-09-28. '||coalesce(v->>'note','')||CASE WHEN v ? 'explanation' THEN E'\nWorked solution: '||(v->>'explanation') ELSE '' END,
   updated_at=now() WHERE id=s.id;
  IF v ? 'parts' THEN UPDATE public.est_source_review SET review_note=review_note||E'\nAdditional separately published questions: '||(SELECT string_agg((partrow.value->>'label')||': '||(partrow.value->>'question_id')||'. '||(partrow.value->>'explanation'),E'\n') FROM jsonb_array_elements(v->'parts') partrow(value)) WHERE id=s.id; END IF;
 END LOOP;
END;
$review$;
SELECT count(*) applied_source_decisions FROM public.audit_log WHERE action='source_review_20260928';
